181	      // Verify registry signature when required.
182	      // Fail closed on missing/invalid signature — silently warning and using
183	      // an unverified registry would let a compromised IPFS gateway (or any
184	      // on-path attacker) swap in attacker-mapped plugin entries that the
185	      // installer would then load unsandboxed.
186	      if (this.config.requireVerification) {
