42	class LRUCache<K, V> {
43	  private cache: Map<K, V> = new Map();
44	  private hits = 0;
45	  private misses = 0;
46	
47	  constructor(private readonly maxSize: number) {}
48	
49	  get(key: K): V | undefined {
50	    const value = this.cache.get(key);
51	    if (value !== undefined) {
52	      // Move to end (most recently used)
53	      this.cache.delete(key);
54	      this.cache.set(key, value);
55	      this.hits++;
56	      return value;
57	    }
58	    this.misses++;
59	    return undefined;
60	  }
61	
62	  set(key: K, value: V): void {
63	    if (this.cache.has(key)) {
64	      this.cache.delete(key);
65	    } else if (this.cache.size >= this.maxSize) {
66	      // Remove oldest (first) entry
67	      const firstKey = this.cache.keys().next().value;
68	      if (firstKey !== undefined) {
69	        this.cache.delete(firstKey);
70	      }
71	    }
72	    this.cache.set(key, value);
73	  }
74	
75	  clear(): void {
76	    this.cache.clear();
77	    this.hits = 0;
78	    this.misses = 0;
79	  }
